from solution import is_woodall


def test_issue_example_383():
    """Example asserts is_woodall(383) == True."""
    assert is_woodall(383) == True  # 6*2**6-1 = 6*64-1 = 383


def test_issue_smallest_1():
    """Woodall rule x == n*2**n-1 gives 1 for n=1."""
    assert is_woodall(1) == True  # 1*2**1-1 = 2-1 = 1


def test_issue_second_7():
    """Woodall rule x == n*2**n-1 gives 7 for n=2."""
    assert is_woodall(7) == True  # 2*2**2-1 = 2*4-1 = 7


def test_issue_third_23():
    """Woodall rule x == n*2**n-1 gives 23 for n=3."""
    assert is_woodall(23) == True  # 3*2**3-1 = 3*8-1 = 23


def test_issue_fifth_159():
    """Woodall rule x == n*2**n-1 gives 159 for n=5."""
    assert is_woodall(159) == True  # 5*2**5-1 = 5*32-1 = 159


def test_issue_large_895():
    """Woodall rule x == n*2**n-1 gives 895 for n=7."""
    assert is_woodall(895) == True  # 7*2**7-1 = 7*128-1 = 895


def test_issue_just_below_382():
    """Non-Woodall just below threshold must return False."""
    assert is_woodall(382) == False  # 383-1 = 382, Woodall is 383


def test_issue_just_above_384():
    """Non-Woodall just above threshold must return False."""
    assert is_woodall(384) == False  # 383+1 = 384, Woodall is 383


def test_issue_zero():
    """Zero is not of form n*2**n-1 so must return False."""
    assert is_woodall(0) == False  # n=1 gives 1, n=2 gives 7, none gives 0


def test_issue_negative():
    """Negative numbers are not Woodall so must return False."""
    assert is_woodall(-5) == False  # min n=1 gives 1, so -5 has no n


def test_contract_mid_63():
    """Documented Woodall check returns True for Woodall numbers."""
    assert is_woodall(63) == True  # 4*2**4-1 = 4*16-1 = 63


def test_contract_between_100():
    """Documented Woodall check returns False for non-Woodall numbers."""
    assert is_woodall(100) == False  # 63 < 100 < 159, so no n gives 100
